// src/adapters/cex/collect.ts
async function collect(ids, hosts, get, now = () => /* @__PURE__ */ new Date()) {
  const out = { venues: {}, failed: [] };
  await Promise.all(
    ids.map(async (id) => {
      const adapter = ADAPTERS.find((a) => a.id === id);
      const host = Object.hasOwn(hosts, id) ? hosts[id] : void 0;
      if (!adapter || !host) {
        out.failed.push(id);
        return;
      }
      try {
        const payloads = {};
        for (const call of adapter.calls)
          payloads[call.name] = await get(`${host}${call.path}`, {
            ...call.method ? { method: call.method } : {},
            ...call.body ? { body: call.body } : {}
          });
        const parsed2 = adapter.parse(payloads);
        if (!parsed2.ok) throw new Error(parsed2.error);
        out.venues[id] = {
          fetched_at: now().toISOString(),
          tickers: parsed2.value.map((t) => [
            t.pair,
            t.base,
            t.quote,
            t.last.toString(),
            t.volumeUsd.toString()
          ])
        };
      } catch {
        out.failed.push(id);
      }
    })
  );
  out.failed.sort();
  return out;
}

